package com.cascade.alarm.data.sound

import androidx.annotation.RawRes
import com.cascade.alarm.R

data class Tone(val key: String, val name: String, val description: String, @RawRes val res: Int)

/**
 * The bundled tones, gentlest first. Generated by scripts/make_tones.py (except Classic, the M1
 * tone). Keys are stored in the database: never rename one, only add.
 */
object Tones {
    val ALL = listOf(
        Tone("dawn", "Dawn", "A soft chord that swells and fades", R.raw.tone_dawn),
        Tone("chimes", "Chimes", "Bells, rising", R.raw.tone_chimes),
        Tone("marimba", "Marimba", "A short wooden melody", R.raw.tone_marimba),
        Tone("classic", "Classic", "The original Cascade alarm", R.raw.tone_classic),
        Tone("pulse", "Pulse", "Four soft beeps", R.raw.tone_pulse),
        Tone("digital", "Digital", "The bedside clock beep", R.raw.tone_digital),
        Tone("rising", "Rising", "A tone that keeps climbing", R.raw.tone_rising),
        Tone("klaxon", "Klaxon", "A harsh buzzer", R.raw.tone_klaxon),
    )

    val DEFAULT: Tone = ALL.first { it.key == "classic" }

    fun byKey(key: String): Tone? = ALL.firstOrNull { it.key == key }
}
